package com.fandazi.feature.address;
import com.fandazi.feature.DomainException; import com.fandazi.feature.auth.UserRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AddressService { private final AddressRepository addresses; private final UserRepository users; public AddressService(AddressRepository addresses,UserRepository users){this.addresses=addresses;this.users=users;} @Transactional public AddressEntity create(Long userId,AddressCommand c){var user=users.findByIdForUpdate(userId).orElseThrow(()->new DomainException("用户不存在"));boolean first=addresses.findByUserIdOrderByDefaultAddressDescIdDesc(userId).isEmpty();if(c.defaultAddress()||first)clearDefault(userId);var address=addresses.save(new AddressEntity(user,c.recipient(),c.phone(),c.detail(),c.defaultAddress()||first));return address;} public List<AddressEntity> list(Long userId){return addresses.findByUserIdOrderByDefaultAddressDescIdDesc(userId);} @Transactional public AddressEntity setDefault(Long userId,Long id){users.findByIdForUpdate(userId).orElseThrow(()->new DomainException("用户不存在"));var address=owned(userId,id); clearOthers(userId,id); address.setDefaultAddress(true); return address;} @Transactional public AddressEntity update(Long userId,Long id,AddressCommand c){var a=owned(userId,id); a.update(c.recipient(),c.phone(),c.detail()); if(c.defaultAddress()) setDefault(userId,id); return a;} @Transactional public void delete(Long userId,Long id){var a=owned(userId,id); if(a.isDefaultAddress()) throw new DomainException("默认地址不能直接删除"); addresses.delete(a);} public AddressEntity owned(Long userId,Long id){return addresses.findByIdAndUserId(id,userId).orElseThrow(()->new DomainException("地址不存在"));} private void clearDefault(Long userId){addresses.findByUserIdOrderByDefaultAddressDescIdDesc(userId).forEach(a->a.setDefaultAddress(false));} private void clearOthers(Long userId,Long id){addresses.findByUserIdOrderByDefaultAddressDescIdDesc(userId).stream().filter(a->!a.getId().equals(id)).forEach(a->a.setDefaultAddress(false));} }
